class Solution:
    def zigzagTraversal(self, grid: List[List[int]]) -> List[int]:
        result = []
        rows = len(grid)
        cols = len(grid[0])
        index = 0
        for r in range(rows):
            if r % 2 == 0:
                indices = range(cols)
            else:
                indices = range(cols - 1, -1, -1)
            for c in indices:
                if index % 2 == 0:
                    result.append(grid[r][c])
                index += 1
        return result

