class Solution:
    def solveQueries(self, nums: List[int], queries: List[int]) -> List[int]:
        n = len(nums)
        groups = defaultdict(list)
        for i, x in enumerate(nums):
            groups[x].append(i)

        index_ans = [-1] * n

        for x, idxs in groups.items():
            k = len(idxs)
            if k == 1:
                continue

            for p in range(k):
                i = idxs[p]
                nxt = idxs[(p + 1) % k]
                prv = idxs[(p - 1) % k]

                d1 = abs(nxt - i)
                if d1 > n - d1:
                    d1 = n - d1

                d2 = abs(i - prv)
                if d2 > n - d2:
                    d2 = n - d2

                index_ans[i] = d1 if d1 < d2 else d2

        return [index_ans[q] for q in queries]

class Solution:
    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)
        vals = [ord(ch) - ord('a') for ch in s]

        dp = [[None] * n for _ in range(n)]
        for i in range(n):
            dp[i][i] = [1] * (k + 1)

        zeros = [0] * (k + 1)

        for length in range(2, n + 1):
            for i in range(0, n - length + 1):
                j = i + length - 1
                diff = abs(vals[i] - vals[j])
                dist = diff if diff <= 13 else 26 - diff

                skip_left = dp[i + 1][j]
                skip_right = dp[i][j - 1]
                inner = dp[i + 1][j - 1] if length >= 3 else zeros

                arr = [0] * (k + 1)
                for budget in range(k + 1):
                    best = skip_left[budget]
                    v = skip_right[budget]
                    if v > best:
                        best = v
                    if budget >= dist:
                        val = 2 + inner[budget - dist]
                        if val > best:
                            best = val
                    arr[budget] = best

                dp[i][j] = arr

        return dp[0][n - 1][k]

