class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        n = len(nums)
        pre = [0] * (n + 1)
        for i in range(n):
            pre[i + 1] = pre[i] + nums[i]

        NEG = -10**18

        # M0[t] = max_{j <= t} (dp[j][0] - pre[j]) = -min_{j <= t} pre[j]
        M_prev = [0] * (n + 1)
        mn = 0
        for t in range(n + 1):
            if pre[t] < mn:
                mn = pre[t]
            M_prev[t] = -mn

        answer = NEG
        for _ in range(k):
            dp_prev = NEG  # dp[i-1][current k]
            M_cur = [0] * (n + 1)
            M_cur[0] = NEG  # b[0][current k] = dp[0][current k] - pre[0]

            for i in range(1, n + 1):
                best = dp_prev  # element i-1 is not selected
                t = i - m
                if t >= 0 and M_prev[t] > NEG:
                    candidate = pre[i] + M_prev[t]
                    if candidate > best:
                        best = candidate

                b = best - pre[i]
                if b > M_cur[i - 1]:
                    M_cur[i] = b
                else:
                    M_cur[i] = M_cur[i - 1]

                dp_prev = best

            answer = dp_prev
            M_prev = M_cur

        return answer

