from collections import deque

class Solution:
    def maxProduct(self, nums, k, limit):
        # Generate all possible nonzero products <= limit from values 1..12.
        products = {1}
        dq = deque([1])
        while dq:
            p = dq.popleft()
            for n in range(2, 13):
                np_ = p * n
                if np_ <= limit and np_ not in products:
                    products.add(np_)
                    dq.append(np_)
        products.add(0)
        products = sorted(products)
        idx_of = {v: i for i, v in enumerate(products)}
        P = len(products)
        zero_idx = 0

        # trans[x][i] = index of products[i]*x if <= limit else -1
        trans = [[-1] * P for _ in range(13)]
        for x in range(13):
            arr = trans[x]
            if x == 0:
                for i in range(P):
                    arr[i] = zero_idx
            elif x == 1:
                for i in range(P):
                    arr[i] = i
            else:
                for i, v in enumerate(products):
                    np_ = v * x
                    if np_ <= limit:
                        arr[i] = idx_of[np_]

        total = sum(nums)
        off = total
        size = 2 * off + 1

        # dp_even: next element is at even index (sign +), current length is even
        # dp_odd : next element is at odd index (sign -), current length is odd
        dp_even = [0] * size
        dp_odd = [0] * size

        for x in nums:
            tx = trans[x]
            new_even = dp_even.copy()  # skip x
            new_odd = dp_odd.copy()    # skip x

            # take x when next sign is + : sum += x, parity flips to odd
            for idx in range(size):
                B = dp_even[idx]
                if not B:
                    continue
                ns = idx + x
                if ns >= size:
                    continue
                new_bits = 0
                b = B
                while b:
                    lsb = b & -b
                    i = lsb.bit_length() - 1
                    b ^= lsb
                    j = tx[i]
                    if j != -1:
                        new_bits |= (1 << j)
                if new_bits:
                    new_odd[ns] |= new_bits

            # take x when next sign is - : sum -= x, parity flips to even
            for idx in range(size):
                B = dp_odd[idx]
                if not B:
                    continue
                ns = idx - x
                if ns < 0:
                    continue
                new_bits = 0
                b = B
                while b:
                    lsb = b & -b
                    i = lsb.bit_length() - 1
                    b ^= lsb
                    j = tx[i]
                    if j != -1:
                        new_bits |= (1 << j)
                if new_bits:
                    new_even[ns] |= new_bits

            dp_even, dp_odd = new_even, new_odd

        if k < -off or k > off:
            return -1
        kk = k + off
        bits = dp_even[kk] | dp_odd[kk]
        if not bits:
            return -1
        return products[bits.bit_length() - 1]

