class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        L = 4 * side

        def to_t(p):
            x, y = p
            if y == 0:
                return x
            if x == side:
                return side + y
            if y == side:
                return 3 * side - x
            # x == 0
            if y == 0:
                return 0
            return L - y

        ts = sorted(to_t(p) for p in points)
        n = len(ts)
        if k <= 1:
            return L

        def feasible(d: int) -> bool:
            if d <= 0:
                return True
            P = ts + [t + L for t in ts]
            m = len(P)
            nxt = [-1] * m
            for v in range(m):
                idx = bisect.bisect_left(P, P[v] + d)
                if idx < m:
                    nxt[v] = idx

            limit_extra = L - d
            for i in range(n):
                j = i
                ok = True
                for _ in range(k - 1):
                    nj = nxt[j]
                    if nj == -1:
                        ok = False
                        break
                    j = nj
                if ok and P[j] <= P[i] + limit_extra:
                    return True
            return False

        lo, hi = 0, L // k
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if feasible(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

