class Solution:
    def minMaxSubarraySum(self, nums: List[int], k: int) -> int:
        return self._sum_max_len_at_most_k(nums, k) - self._sum_max_len_at_most_k([-x for x in nums], k)

    def _sum_max_len_at_most_k(self, nums: List[int], k: int) -> int:
        n = len(nums)
        K = k - 1

        prev_ge = [-1] * n
        stack = []
        for i in range(n):
            x = nums[i]
            while stack and nums[stack[-1]] < x:
                stack.pop()
            prev_ge[i] = stack[-1] if stack else -1
            stack.append(i)

        next_gt = [n] * n
        stack = []
        for i in range(n - 1, -1, -1):
            x = nums[i]
            while stack and nums[stack[-1]] <= x:
                stack.pop()
            next_gt[i] = stack[-1] if stack else n
            stack.append(i)

        total = 0
        for i in range(n):
            left_len = i - prev_ge[i]
            right_len = next_gt[i] - i
            total += nums[i] * self._count_pairs(left_len, right_len, K)
        return total

    @staticmethod
    def _count_pairs(left_len: int, right_len: int, K: int) -> int:
        L, R = left_len, right_len
        if K >= L + R - 2:
            return L * R

        m = min(L - 1, K)
        if m < 0:
            return 0

        s = K + 1 - R
        if s < 0:
            return (m + 1) * (K + 1) - (m * (m + 1) // 2)
        if s >= m:
            return (m + 1) * R
        return (s + 1) * R + ((m - s) * (R + K - m) // 2)

