class Solution:
    def _count_completions(
        self,
        prefix: List[int],
        n: int,
        fact: List[int],
        patterns: List[tuple],
        odd_count: int,
        even_count: int,
    ) -> int:
        used_odd = 0
        used_even = 0
        for x in prefix:
            if x & 1:
                used_odd += 1
            else:
                used_even += 1

        total = 0
        for pat in patterns:
            ok = True
            for i, x in enumerate(prefix):
                if (x & 1) != pat[i]:
                    ok = False
                    break
            if not ok:
                continue
            rem_odd = odd_count - used_odd
            rem_even = even_count - used_even
            total += fact[rem_odd] * fact[rem_even]
        return total

    def permute(self, n: int, k: int) -> List[int]:
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i

        odd_count = (n + 1) // 2
        even_count = n // 2

        if n % 2 == 0:
            m = n // 2
            patterns = [(1, 0) * m, (0, 1) * m]
        else:
            m = (n - 1) // 2
            patterns = [(1, 0) * m + (1,)]

        total = self._count_completions(
            [], n, fact, patterns, odd_count, even_count
        )
        if k > total:
            return []

        used = [False] * (n + 1)
        result = []

        for _ in range(n):
            chosen = None
            for v in range(1, n + 1):
                if used[v]:
                    continue
                count = self._count_completions(
                    result + [v], n, fact, patterns, odd_count, even_count
                )
                if count >= k:
                    chosen = v
                    break
                k -= count

            if chosen is None:
                return []

            result.append(chosen)
            used[chosen] = True

        return result
